-- Speglar det som lades på databasen 2026-09-16 via apply_migration i två delar:
--   jmhz2_order_code_from_catalogue_part_01  (familjen jmhz2 in, backup, schema, familjens rad, parametrar, värdelista, rensning av regler)
--   jmhz2_order_code_from_catalogue_part_02  (regler 1–24, dokumentkarta)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts jmhz2):
--   regler  24   md5 c46b9de403fd77c17422b82bb25a2332   villkor 99ae8d24fc948cb349f339b6cd49c462
--   värden  37   md5 85a3776c6023b268ca1f50aa4c63a0b6
--   schema       md5 9c3844b59765e168ca4fc18dd37d2b60
-- Verifierat live: /sv/configurator/jmhz2 bygger JMHZ2-16D-M9BW (nyckelns exempel sida 9) och
-- JMHZ2-20C2-M9NAVZ4; stoppar givare med -X6900A (ingen givarposition, sida 20) och tre givare
-- med -X7460 (sida 21).
--
-- JMHZ2: beställnyckeln enligt SMC Compact Type Parallel Style Air Gripper JMHZ2 Series (sida 9).
-- GENERERAD ur src/lib/catalog/jmhz2.ts -- redigera inte för hand.
--
-- Ny familj jmhz2 i kategorin gripper: JMHZ2-{ø}{verkan}{finger}-{givare}{kabel}{antal}-{special},
-- t.ex. JMHZ2-16D-M9BW (nyckelns exempel sida 9). Fyra storlekar, tre
-- verkningssätt, två fingeralternativ, 18 givare, -X50/-X6900A/-X6900B/-X7460.
-- Katalogfilen smc-kat-mhz2.pdf (hämtad som MHZ2) är detta kapitel; den
-- kopplas nu till jmhz2 i knowledge_doc_families. Inga produktrader finns.

begin;


insert into configurator_families (slug, name, title, description, category_slug)
values ('jmhz2', 'JMHZ2', 'JMHZ2', '', 'gripper')
on conflict (slug) do update set name = excluded.name;


create schema if not exists backup;
create table if not exists backup.jmhz2_before_20260916 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'jmhz2'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'jmhz2'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'jmhz2';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-JMHZ2-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Storlek","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"8","label":"ø8 mm (motsvarar MHZ2-10)"},{"v":"12","label":"ø12 mm (motsvarar MHZ2-16)"},{"v":"16","label":"ø16 mm (motsvarar MHZ2-20)"},{"v":"20","label":"ø20 mm (motsvarar MHZ2-25)"}]},{"id":"action","step":2,"title_sv":"Verkan","title_en":"Action","required":true,"type":"single_select","options":[{"v":"D","label":"Dubbelverkande"},{"v":"S","label":"Enkelverkande, normalt öppet"},{"v":"C","label":"Enkelverkande, normalt stängt"}]},{"id":"finger","step":3,"title_sv":"Fingeralternativ (standard är basfingrar)","title_en":"Finger option (basic fingers are standard)","required":false,"type":"single_select","options":[{"v":"1","label":"Fingrar med sidogängad montering"},{"v":"2","label":"Fingrar med genomgående hål i öppnings-/stängningsriktningen"}]},{"id":"switch","step":4,"title_sv":"Givare (magneten är inbyggd)","title_en":"Auto switch (the magnet is built in)","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinkelrät anslutning"},{"v":"M9P","label":"D-M9P, 3-tråd PNP"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinkelrät anslutning"},{"v":"M9B","label":"D-M9B, 2-tråd"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinkelrät anslutning"},{"v":"M9NW","label":"D-M9NW, 3-tråd NPN, tvåfärgsindikering"},{"v":"M9NWV","label":"D-M9NWV, 3-tråd NPN, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9PW","label":"D-M9PW, 3-tråd PNP, tvåfärgsindikering"},{"v":"M9PWV","label":"D-M9PWV, 3-tråd PNP, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9NA","label":"D-M9NA, 3-tråd NPN, vattentät, tvåfärgsindikering"},{"v":"M9NAV","label":"D-M9NAV, 3-tråd NPN, vattentät, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9PA","label":"D-M9PA, 3-tråd PNP, vattentät, tvåfärgsindikering"},{"v":"M9PAV","label":"D-M9PAV, 3-tråd PNP, vattentät, tvåfärgsindikering, vinkelrät anslutning"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, tvåfärgsindikering"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, tvåfärgsindikering, vinkelrät anslutning"}]},{"id":"lead","step":5,"title_sv":"Givarens kabellängd (standard är 0,5 m)","title_en":"Auto switch lead wire length (0.5 m is standard)","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":6,"title_sv":"Antal givare (standard är två)","title_en":"Number of auto switches (two is standard)","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre givare (n st)"},{"v":"4","label":"Fyra givare (n st)"}]},{"id":"mto","step":7,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"X50","label":"-X50 Utan magnet"},{"v":"X6900A","label":"-X6900A Styrpinnar på sidomonteringsytan A (portsidan)"},{"v":"X6900B","label":"-X6900B Styrpinnar på sidomonteringsytan B"},{"v":"X7460","label":"-X7460 Sidomonterad givare (plåt på två sidoytor, egen kropp)"}]}]}'::jsonb,
        'SMC JMHZ2 kompakt parallellgripdon', 'SMC JMHZ2 compact parallel gripper', 'gripper')
on conflict (schema_id) do update set
  schema_json = excluded.schema_json,
  title_sv = excluded.title_sv,
  title_en = excluded.title_en;

update configurator_families set
  title = 'Kompakt parallellgripdon JMHZ2 ø8–20, dubbel- eller enkelverkande, med inbyggd magnet',
  description = 'SMC JMHZ2 compact type parallel style air gripper: ø8, 12, 16 and 20 (equivalent to MHZ2-10/16/20/25 with a smaller body), double acting or single acting (normally open/closed), 4–14 mm stroke, gripping force 4.5–72 N per finger at 0.5 MPa, finger options with side tapped mounting or through-holes, built-in magnet with D-M9 auto switches, -X50 without magnet, -X6900 positioning pins, -X7460 lateral auto switch mounting.',
  stroke_min_mm = null,
  stroke_max_mm = null,
  order_code_template = 'JMHZ2-{bore}{action}{finger}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-JMHZ2-V1'
where slug = 'jmhz2';


delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'jmhz2';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'jmhz2';

insert into configurator_params (family_id, param_key, label, param_type, sort_order, required, min_value, max_value, show_code)
select f.id, r.param_key, r.label, r.param_type, r.sort_order, r.required, r.min_value, r.max_value, true
from configurator_families f,
     jsonb_to_recordset('[{"param_key":"bore","label":"Storlek","param_type":"select","sort_order":1,"required":true,"min_value":null,"max_value":null},{"param_key":"action","label":"Verkan","param_type":"select","sort_order":2,"required":true,"min_value":null,"max_value":null},{"param_key":"finger","label":"Fingeralternativ (standard är basfingrar)","param_type":"select","sort_order":3,"required":false,"min_value":null,"max_value":null},{"param_key":"switch","label":"Givare (magneten är inbyggd)","param_type":"select","sort_order":4,"required":false,"min_value":null,"max_value":null},{"param_key":"lead","label":"Givarens kabellängd (standard är 0,5 m)","param_type":"select","sort_order":5,"required":false,"min_value":null,"max_value":null},{"param_key":"count","label":"Antal givare (standard är två)","param_type":"select","sort_order":6,"required":false,"min_value":null,"max_value":null},{"param_key":"mto","label":"Specialutförande","param_type":"select","sort_order":7,"required":false,"min_value":null,"max_value":null}]'::jsonb)
       as r(param_key text, label text, param_type text, sort_order int, required boolean,
            min_value numeric, max_value numeric)
where f.slug = 'jmhz2';

insert into configurator_param_values (param_id, code, label, sort_order)
select p.id, r.code, r.label, r.sort_order
from jsonb_to_recordset('[{"param_key":"bore","code":"8","label":"ø8 mm (motsvarar MHZ2-10)","sort_order":0},{"param_key":"bore","code":"12","label":"ø12 mm (motsvarar MHZ2-16)","sort_order":1},{"param_key":"bore","code":"16","label":"ø16 mm (motsvarar MHZ2-20)","sort_order":2},{"param_key":"bore","code":"20","label":"ø20 mm (motsvarar MHZ2-25)","sort_order":3},{"param_key":"action","code":"D","label":"Dubbelverkande","sort_order":0},{"param_key":"action","code":"S","label":"Enkelverkande, normalt öppet","sort_order":1},{"param_key":"action","code":"C","label":"Enkelverkande, normalt stängt","sort_order":2},{"param_key":"finger","code":"1","label":"Fingrar med sidogängad montering","sort_order":0},{"param_key":"finger","code":"2","label":"Fingrar med genomgående hål i öppnings-/stängningsriktningen","sort_order":1},{"param_key":"switch","code":"M9N","label":"D-M9N, 3-tråd NPN","sort_order":0},{"param_key":"switch","code":"M9NV","label":"D-M9NV, 3-tråd NPN, vinkelrät anslutning","sort_order":1},{"param_key":"switch","code":"M9P","label":"D-M9P, 3-tråd PNP","sort_order":2},{"param_key":"switch","code":"M9PV","label":"D-M9PV, 3-tråd PNP, vinkelrät anslutning","sort_order":3},{"param_key":"switch","code":"M9B","label":"D-M9B, 2-tråd","sort_order":4},{"param_key":"switch","code":"M9BV","label":"D-M9BV, 2-tråd, vinkelrät anslutning","sort_order":5},{"param_key":"switch","code":"M9NW","label":"D-M9NW, 3-tråd NPN, tvåfärgsindikering","sort_order":6},{"param_key":"switch","code":"M9NWV","label":"D-M9NWV, 3-tråd NPN, tvåfärgsindikering, vinkelrät anslutning","sort_order":7},{"param_key":"switch","code":"M9PW","label":"D-M9PW, 3-tråd PNP, tvåfärgsindikering","sort_order":8},{"param_key":"switch","code":"M9PWV","label":"D-M9PWV, 3-tråd PNP, tvåfärgsindikering, vinkelrät anslutning","sort_order":9},{"param_key":"switch","code":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering","sort_order":10},{"param_key":"switch","code":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinkelrät anslutning","sort_order":11},{"param_key":"switch","code":"M9NA","label":"D-M9NA, 3-tråd NPN, vattentät, tvåfärgsindikering","sort_order":12},{"param_key":"switch","code":"M9NAV","label":"D-M9NAV, 3-tråd NPN, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":13},{"param_key":"switch","code":"M9PA","label":"D-M9PA, 3-tråd PNP, vattentät, tvåfärgsindikering","sort_order":14},{"param_key":"switch","code":"M9PAV","label":"D-M9PAV, 3-tråd PNP, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":15},{"param_key":"switch","code":"M9BA","label":"D-M9BA, 2-tråd, vattentät, tvåfärgsindikering","sort_order":16},{"param_key":"switch","code":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, tvåfärgsindikering, vinkelrät anslutning","sort_order":17},{"param_key":"lead","code":"M","label":"1 m kabel","sort_order":0},{"param_key":"lead","code":"L","label":"3 m kabel","sort_order":1},{"param_key":"lead","code":"Z","label":"5 m kabel","sort_order":2},{"param_key":"count","code":"S","label":"En givare (standard är två)","sort_order":0},{"param_key":"count","code":"3","label":"Tre givare (n st)","sort_order":1},{"param_key":"count","code":"4","label":"Fyra givare (n st)","sort_order":2},{"param_key":"mto","code":"X50","label":"-X50 Utan magnet","sort_order":0},{"param_key":"mto","code":"X6900A","label":"-X6900A Styrpinnar på sidomonteringsytan A (portsidan)","sort_order":1},{"param_key":"mto","code":"X6900B","label":"-X6900B Styrpinnar på sidomonteringsytan B","sort_order":2},{"param_key":"mto","code":"X7460","label":"-X7460 Sidomonterad givare (plåt på två sidoytor, egen kropp)","sort_order":3}]'::jsonb)
       as r(param_key text, code text, label text, sort_order int)
join configurator_params p on p.param_key = r.param_key
join configurator_families f on f.id = p.family_id and f.slug = 'jmhz2';

delete from config_rules where schema_id = 'SCHEMA-JMHZ2-V1';


insert into config_rules (schema_id, severity, if_json, message_sv, message_en, goto_step)
select 'SCHEMA-JMHZ2-V1', r->>'severity', r->'if_json',
       r->>'message_sv', r->>'message_en', r->>'goto_step'
from jsonb_array_elements('[{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"in":[{"var":"mto"},["X50"]]}]},"message_sv":"-X50 är utan magnet — givare kan inte användas (sida 10).","message_en":"-X50 is without a magnet — auto switches cannot be used (page 10).","goto_step":"jmhz2-mto"},{"severity":"error","if_json":{"and":[{"!=":[{"var":"switch"},""]},{"in":[{"var":"mto"},["X6900A","X6900B"]]}]},"message_sv":"Nyckeln för -X6900 (styrpinnar) har ingen givarposition: JMHZ2-□□-X6900A/B (sida 20).","message_en":"The -X6900 key (positioning pins) has no auto switch position: JMHZ2-□□-X6900A/B (page 20).","goto_step":"jmhz2-mto"},{"severity":"error","if_json":{"and":[{"in":[{"var":"count"},["3","4"]]},{"in":[{"var":"mto"},["X7460"]]}]},"message_sv":"-X7460 beställs med en (S) eller två givare; tre eller fler efter förfrågan hos SMC (sida 21).","message_en":"-X7460 is ordered with one (S) or two auto switches; three or more on request from SMC (page 21).","goto_step":"jmhz2-count"},{"severity":"error","if_json":{"and":[{"==":[{"var":"switch"},""]},{"or":[{"!=":[{"var":"lead"},""]},{"!=":[{"var":"count"},""]}]}]},"message_sv":"Kabellängd och antal hör till givaren — välj en givare först.","message_en":"Lead wire length and quantity belong to the auto switch — choose a switch first.","goto_step":"jmhz2-switch"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"lead"},""]},{"in":[{"var":"switch"},["M9NA","M9NAV","M9PA","M9PAV","M9BA","M9BAV"]]}]},"message_sv":"Kabellängd 0,5 m (ingen bokstav) tillverkas på beställning för D-M9NA/M9PA/M9BA (även V-typerna) (sida 9, ○).","message_en":"Lead wire length 0.5 m (no letter) is produced upon receipt of order for D-M9NA/M9PA/M9BA (V types too) (page 9, ○).","goto_step":"jmhz2-lead"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"lead"},"M"]},{"in":[{"var":"switch"},["M9NA","M9NAV","M9PA","M9PAV","M9BA","M9BAV"]]}]},"message_sv":"Kabellängd 1 m (M) tillverkas på beställning för D-M9NA/M9PA/M9BA (även V-typerna) (sida 9, ○).","message_en":"Lead wire length 1 m (M) is produced upon receipt of order for D-M9NA/M9PA/M9BA (V types too) (page 9, ○).","goto_step":"jmhz2-lead"},{"severity":"warn","if_json":{"and":[{"==":[{"var":"lead"},"Z"]},{"in":[{"var":"switch"},["M9N","M9NV","M9P","M9PV","M9B","M9BV","M9NW","M9NWV","M9PW","M9PWV","M9BW","M9BWV","M9NA","M9NAV","M9PA","M9PAV","M9BA","M9BAV"]]}]},"message_sv":"Kabellängd 5 m (Z) tillverkas på beställning för D-M9N/M9P/M9B/M9NW/M9PW/M9BW/M9NA/M9PA/M9BA (även V-typerna) (sida 9, ○).","message_en":"Lead wire length 5 m (Z) is produced upon receipt of order for D-M9N/M9P/M9B/M9NW/M9PW/M9BW/M9NA/M9PA/M9BA (V types too) (page 9, ○).","goto_step":"jmhz2-lead"},{"severity":"warn","if_json":{"in":[{"var":"switch"},["M9NA","M9NAV","M9PA","M9PAV","M9BA","M9BAV"]]},"message_sv":"De vattentäta givarna D-M9NA/M9PA/M9BA går att montera, men SMC garanterar inte vattentätheten (sida 9, ∗2).","message_en":"The water-resistant switches D-M9NA/M9PA/M9BA can be mounted, but SMC cannot guarantee water resistance (page 9, ∗2).","goto_step":"jmhz2-switch"},{"severity":"info","if_json":{"in":[{"var":"switch"},["M9NW","M9NWV","M9PW","M9PWV","M9BW","M9BWV"]]},"message_sv":"Tvåfärgsindikering: ställ in givaren så att den lyser rött i rätt läge för säker detektering (sida 9). Givare med kortare längd finns på beställning.","message_en":"Two-colour indication: set the switch so that it lights red at the proper position for reliable detection (page 9). A shorter switch is available on request.","goto_step":"jmhz2-switch"},{"severity":"info","if_json":{"and":[{"==":[{"var":"bore"},"8"]},{"==":[{"var":"action"},"D"]}]},"message_sv":"JMHZ2-8D: gripkraft per finger 7,8 N yttre/10,5 N inre grepp vid 0,5 MPa (L = 20 mm), slag 4 mm båda sidor, 0,15–0,7 MPa, vikt 31 g utan givare; motsvarar MHZ2-10 (sida 4 och 10).","message_en":"JMHZ2-8D: gripping force per finger 7.8 N external/10.5 N internal grip at 0.5 MPa (L = 20 mm), stroke 4 mm both sides, 0.15–0.7 MPa, we